--
-- Table structure for table `upload_jobs`
--

DROP TABLE IF EXISTS `upload_jobs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `upload_jobs` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `video_id` int DEFAULT NULL COMMENT 'Preenchido após INSERT inicial na tabela videos',
  `tmp_video_path` varchar(700) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Caminho absoluto do ficheiro raw temporário',
  `original_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `hashtags` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_public` tinyint(1) NOT NULL DEFAULT '1',
  `music_track_data` text COLLATE utf8mb4_unicode_ci COMMENT 'JSON da faixa de música selecionada',
  `music_mode` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'mix',
  `music_volume` float NOT NULL DEFAULT '0.25',
  `music_start` float NOT NULL DEFAULT '0',
  `ad_flow` tinyint(1) NOT NULL DEFAULT '0',
  `status` enum('queued','processing','done','failed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'queued',
  `progress_msg` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Mensagem de progresso para o frontend',
  `error_message` text COLLATE utf8mb4_unicode_ci,
  `attempts` int NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `started_at` datetime DEFAULT NULL,
  `finished_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_status` (`status`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_video_id` (`video_id`),
  KEY `idx_created` (`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=361 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Fila de jobs de processamento de vídeo em background';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `upload_jobs`
--

LOCK TABLES `upload_jobs` WRITE;
/*!40000 ALTER TABLE `upload_jobs` DISABLE KEYS */;
